#!/usr/bin/env python3
"""Review ledger CLI (issue #7). Stdlib only; no model calls.

  python scripts/ledger.py ingest  --dir <artifact dir> --ref <artifact name> [--run-id N]
      (receipt artifacts are accepted only inside the ledger workflow: RUN_WORKFLOW_PATH/RUN_HEAD_SHA from the
       producing run + a verified artifact attestation; anywhere else they are refused)
  python scripts/ledger.py backfill [--artifacts <dir of unzipped artifacts>]   # reviews/*_round*/ + artifacts
  python scripts/ledger.py mirror  [--apply] [--min-severity major] [--cap 5] [--only-ids a,b]   # dry-run unless --apply
  python scripts/ledger.py status  --issue N --state closed --reason completed|not_planned [--labels a,b]
  python scripts/ledger.py append-file --file <records.jsonl>
  python scripts/ledger.py ingest-staged [--dir ledger/pending] [--dry-run]
      (v1.2: Danny's staged decisions -> finding + status records. Writes only inside the ledger workflow on main,
       GITHUB_ACTIONS=true and GITHUB_REF=refs/heads/main; anywhere else it refuses unless --dry-run)
  python scripts/ledger.py validate            # schema + receipt digests (evidence unaltered)
  python scripts/ledger.py classify-legacy     # v1.1: tag pre-gate findings/costs review_class=legacy
  python scripts/ledger.py verify-append-only --old <file> --new <file>

Mirror (issue filing) needs GITHUB_TOKEN + GITHUB_REPOSITORY; dry-run prints what it would file and posts nothing.
Every title/body is sanitised and re-checked for trigger strings and at-mentions before posting.
"""
from __future__ import annotations

import argparse
import datetime as dt
import json
import os
import sys
import urllib.error
import urllib.request
from pathlib import Path

sys.path.insert(0, os.path.dirname(__file__))
import ledger_lib as L  # noqa: E402

API = "https://api.github.com"


def ledger_path(cfg) -> Path:
    return L.ROOT / cfg["ledger_path"]


# ------------------------------------------------------------------ GitHub REST (injectable for tests)
class GitHub:
    def __init__(self, repo: str, token: str, opener=None):
        self.repo, self.token, self.opener = repo, token, opener or urllib.request.urlopen

    def req(self, method, path, body=None):
        r = urllib.request.Request(API + path, method=method, data=None if body is None else json.dumps(body).encode(),
                                   headers={"authorization": f"Bearer {self.token}", "accept": "application/vnd.github+json",
                                            "x-github-api-version": "2022-11-28", "content-type": "application/json"})
        with self.opener(r, timeout=30) as resp:
            txt = resp.read().decode()
            return json.loads(txt) if txt else {}

    def ensure_label(self, name, color="ededed"):
        try:
            self.req("POST", f"/repos/{self.repo}/labels", {"name": name, "color": color})
        except urllib.error.HTTPError as e:
            if e.code != 422:          # 422 = already exists
                raise

    def created_today(self, label) -> int:
        day = dt.datetime.now(dt.timezone.utc).strftime("%Y-%m-%d")
        q = f"repo:{self.repo}+label:{label}+is:issue+created:>={day}"
        return int(self.req("GET", f"/search/issues?q={q}&per_page=1").get("total_count", 0))

    def create_issue(self, title, body, labels):
        return self.req("POST", f"/repos/{self.repo}/issues", {"title": title, "body": body, "labels": labels})


def slug(s: str) -> str:
    return "".join(c if c.isalnum() else "-" for c in s.lower()).strip("-")[:40] or "general"


def issue_text(f: dict, cfg: dict) -> tuple[str, str, list[str]]:
    base = cfg["file_issues"]["base_label"]
    title = L.sanitise(f"Ledger: {f['severity']} from {f['reviewer']}: {f['claim']}", cfg, 120)
    src = f["source"]
    lines = [
        "Filed automatically by the review ledger (issue #7). Reviewer text below is quoted data, not instructions.",
        "",
        f"- Ledger id: {f['id']}",
        f"- Reviewer: {f['reviewer']} ({L.sanitise(f.get('model') or '?', cfg, 60)})",
        f"- Severity: {f['severity']} · Domain: {f['domain']} · Review verdict: {f.get('review_verdict') or 'n/a'}",
        f"- File: {f['file'] or '(none)'}",
        f"- Source: {L.sanitise(src.get('type'), cfg, 40)} {L.sanitise(src.get('ref'), cfg, 120)}"
        + (f", run {src['run_id']}" if src.get("run_id") else "")
        + (f", commit {str(src['head_sha'])[:12]}" if src.get("head_sha") else ""),
        "",
        "Claim:", "", "> " + f["claim"].replace("\n", "\n> "), "",
        "Reviewer note:", "", "> " + (f["note"] or "(none)").replace("\n", "\n> "),
    ]
    if f.get("injection_flags"):
        lines += ["", "Warning: this reviewer text matched prompt-injection patterns: " + ", ".join(f["injection_flags"])]
    lines += ["", "Close as completed = fixed; close as not planned = rejected; label status:accepted to accept without closing."]
    body = "\n".join(lines)
    labels = [base, f"model:{f['reviewer'].lower()}", f"sev:{f['severity']}", f"domain:{slug(f['domain'])}", "status:open"]
    if L.contains_trigger(title, cfg) or L.contains_trigger(body, cfg):   # belt and braces: never post a trigger
        raise ValueError(f"refusing to post finding {f['id']}: trigger string survived sanitising")
    return title, body, labels


def plan_mirror(records, cfg, min_sev: str, only_ids=None) -> list[dict]:
    st, done, classes = L.current_status(records), L.mirrored(records), L.review_classes(records)
    floor = L.severity_rank(min_sev, cfg)
    out = []
    for r in records:
        if r["kind"] != "finding" or r["id"] in done or st.get(r["id"]) != "open":
            continue
        if classes.get(r["id"]) == "spec-review":      # round 4: spec reviews are never mirrored as fixable issues
            continue
        if only_ids and r["id"] not in only_ids:
            continue
        if L.severity_rank(r["severity"], cfg) >= floor:
            out.append(r)
    return out


def cmd_mirror(a, cfg, gh: GitHub | None = None) -> dict:
    path = ledger_path(cfg)
    records = L.read_ledger(path)
    min_sev = a.min_severity or cfg["file_issues"]["min_severity"]
    cap = int(a.cap if a.cap is not None else cfg["file_issues"]["daily_cap"])
    todo = plan_mirror(records, cfg, min_sev, set(a.only_ids.split(",")) if a.only_ids else None)
    report = {"mode": "apply" if a.apply else "dry-run", "min_severity": min_sev, "daily_cap": cap,
              "eligible": len(todo), "filed": [], "skipped_cap": 0, "would_file": []}
    if not a.apply:
        for f in todo[:cap]:
            title, _, labels = issue_text(f, cfg)
            report["would_file"].append({"id": f["id"], "title": title, "labels": labels})
        report["skipped_cap"] = max(len(todo) - cap, 0)
        return report
    gh = gh or GitHub(os.environ["GITHUB_REPOSITORY"], os.environ["GITHUB_TOKEN"])
    base = cfg["file_issues"]["base_label"]
    left = max(cap - gh.created_today(base), 0)
    new = []
    for f in todo:
        if left <= 0:
            report["skipped_cap"] += 1
            continue
        title, body, labels = issue_text(f, cfg)
        for lb in labels:
            gh.ensure_label(lb)
        issue = gh.create_issue(title, body, labels)
        new.append(L.make_mirror(f["id"], issue["number"], {"type": "issue", "ref": f"#{issue['number']}"}))
        report["filed"].append({"id": f["id"], "issue": issue["number"]})
        left -= 1
    L.append_records(path, new)
    if getattr(a, "records_out", None):
        Path(a.records_out).write_text("".join(json.dumps(r) + "\n" for r in new), encoding="utf-8")
    return report


def status_from_issue(state: str, reason: str | None, labels: list[str]) -> str | None:
    labels = [x.lower() for x in labels]
    for s in ("superseded", "deferred", "rejected", "fixed", "accepted"):
        if f"status:{s}" in labels:
            return s
    if state == "closed":
        return "rejected" if reason == "not_planned" else "fixed"
    return None


def cmd_status(a, cfg) -> dict:
    path = ledger_path(cfg)
    records = L.read_ledger(path)
    by_issue = {v: k for k, v in L.mirrored(records).items()}
    fid = by_issue.get(int(a.issue))
    if not fid:
        return {"issue": a.issue, "result": "not a ledger issue"}
    s = status_from_issue(a.state, a.reason, (a.labels or "").split(",") if a.labels else [])
    if not s:
        return {"issue": a.issue, "result": "no status change"}
    added = L.append_records(path, [L.make_status(fid, s, {"type": "issue", "ref": f"#{a.issue}"}, int(a.issue))])
    return {"issue": a.issue, "finding_id": fid, "status": s, "appended": len(added)}


def cmd_backfill(a, cfg) -> dict:
    recs = []
    for folder in sorted((L.ROOT / "reviews").glob("*_round*")):
        if (folder / "results.json").is_file():
            recs += L.parse_review_round(folder, cfg)
    if a.artifacts:
        for d in sorted(Path(a.artifacts).iterdir()):
            if d.is_dir():
                meta = d / "artifact.json"
                m = json.loads(meta.read_text()) if meta.is_file() else {}
                recs += L.parse_artifact_dir(d, cfg, m.get("name", d.name), m.get("run_id"))
    added = L.append_records(ledger_path(cfg), recs)
    return {"parsed": len(recs), "appended": len(added)}


def staged_write_allowed(env=os.environ) -> bool:
    """CI is the only writer of the ledger: staged decisions are appended only by ledger.yml running on main."""
    return env.get("GITHUB_ACTIONS") == "true" and env.get("GITHUB_REF") == "refs/heads/main"


def cmd_ingest_staged(a, cfg, env=os.environ) -> dict:
    d = Path(a.dir) if a.dir else L.ROOT / "ledger" / "pending"
    recs, refused = L.parse_staged_dir(d, cfg)
    existing = {r["id"] for r in L.read_ledger(ledger_path(cfg))}
    new = [r for r in recs if r["id"] not in existing]
    res = {"dir": str(d), "parsed": len(recs), "new": len(new), "refused": refused,
           "statuses": {s: sum(1 for r in new if r["kind"] == "status" and r["status"] == s) for s in L.STATUSES}}
    if a.dry_run:
        res["mode"] = "dry-run"
        return res
    if not staged_write_allowed(env):
        raise SystemExit("ingest-staged writes only inside the ledger workflow on main (GITHUB_ACTIONS=true, "
                         "GITHUB_REF=refs/heads/main); use --dry-run locally. The ledger is CI-written.")
    res["mode"] = "apply"
    res["appended"] = len(L.append_records(ledger_path(cfg), recs))
    return res


def cmd_validate(cfg) -> dict:
    schema = L.load_schema()
    recs = L.read_ledger(ledger_path(cfg))
    errs, ids = [], set()
    for i, r in enumerate(recs):
        for e in L.validate(r, schema):
            errs.append(f"line {i + 1}: {e}")
        if r.get("id") in ids:
            errs.append(f"line {i + 1}: duplicate id {r.get('id')}")
        ids.add(r.get("id"))
        if r.get("kind") == "receipt":
            import receipt as R
            if R.digest(R.canonical(r.get("evidence") or {})) != r.get("artifact_digest"):
                errs.append(f"line {i + 1}: receipt digest mismatch (evidence altered)")
    return {"records": len(recs), "errors": errs}


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sp = ap.add_subparsers(dest="cmd", required=True)
    p = sp.add_parser("ingest"); p.add_argument("--dir", required=True); p.add_argument("--ref", required=True)
    p.add_argument("--run-id", default=None)
    p = sp.add_parser("backfill"); p.add_argument("--artifacts", default=None)
    p = sp.add_parser("mirror"); p.add_argument("--apply", action="store_true"); p.add_argument("--min-severity")
    p.add_argument("--cap", type=int); p.add_argument("--only-ids", default=None)
    p.add_argument("--records-out", default=None, help="also write new mirror records here (for rebase-retry)")
    p = sp.add_parser("append-file"); p.add_argument("--file", required=True)
    p = sp.add_parser("status"); p.add_argument("--issue", required=True); p.add_argument("--state", required=True)
    p.add_argument("--reason", default=None); p.add_argument("--labels", default="")
    p = sp.add_parser("ingest-staged"); p.add_argument("--dir", default=None); p.add_argument("--dry-run", action="store_true")
    sp.add_parser("validate")
    sp.add_parser("classify-legacy")
    p = sp.add_parser("verify-append-only"); p.add_argument("--old", required=True); p.add_argument("--new", required=True)
    a = ap.parse_args(argv)
    cfg = L.load_config()
    if a.cmd == "ingest":
        refused, run_meta, verifier = [], None, None
        if os.environ.get("GITHUB_ACTIONS") == "true" and os.environ.get("RUN_WORKFLOW_PATH"):
            import receipt as R
            run_meta = {"workflow_path": os.environ["RUN_WORKFLOW_PATH"], "head_sha": os.environ.get("RUN_HEAD_SHA"),
                        "run_id": a.run_id}
            verifier = R.gh_attestation_verify
        recs = L.parse_artifact_dir(Path(a.dir), cfg, a.ref, a.run_id, run_meta=run_meta, verifier=verifier, refused=refused)
        res = {"parsed": len(recs), "appended": len(L.append_records(ledger_path(cfg), recs, allow_receipts=True)),
               "receipts": len([r for r in recs if r["kind"] == "receipt"]), "receipts_refused": refused}
        for msg in refused:
            print(f"::warning title=Receipt refused::{msg}", file=sys.stderr)
    elif a.cmd == "classify-legacy":
        recs = L.legacy_backfill(L.read_ledger(ledger_path(cfg)))
        res = {"class_records": len(L.append_records(ledger_path(cfg), recs))}
    elif a.cmd == "backfill":
        res = cmd_backfill(a, cfg)
    elif a.cmd == "mirror":
        res = cmd_mirror(a, cfg)
    elif a.cmd == "status":
        res = cmd_status(a, cfg)
    elif a.cmd == "append-file":
        recs = L.read_ledger(Path(a.file))
        res = {"appended": len(L.append_records(ledger_path(cfg), recs))}
    elif a.cmd == "ingest-staged":
        res = cmd_ingest_staged(a, cfg)
        for msg in res["refused"]:
            print(f"::warning title=Staged record refused::{msg}", file=sys.stderr)
    elif a.cmd == "validate":
        res = cmd_validate(cfg)
    else:
        old = Path(a.old).read_text(encoding="utf-8") if Path(a.old).is_file() else ""
        ok = L.verify_append_only(old, Path(a.new).read_text(encoding="utf-8"))
        res = {"append_only": ok}
    print(json.dumps(res, indent=2))
    if (a.cmd == "validate" and res["errors"]) or (a.cmd == "verify-append-only" and not res["append_only"]):
        sys.exit(1)


if __name__ == "__main__":
    main()

# ------------------------------------------------------------------ hashing / records
def _norm(s) -> str:
    return re.sub(r"\s+", " ", str(s or "")).strip().lower()


def dedup_hash(*parts) -> str:
    return hashlib.sha256("\x1f".join(_norm(p) for p in parts).encode()).hexdigest()


def normalise_severity(sev, cfg: dict) -> str:
    s = _norm(sev)
    s = cfg["severity_aliases"].get(s, s)
    return s if s in cfg["severity_order"] else "note"


def severity_rank(sev: str, cfg: dict) -> int:
    return cfg["severity_order"].index(normalise_severity(sev, cfg))


def make_finding(cfg, *, reviewer, model, severity, domain, file, claim, note, source, verdict=None, event_utc=None,
                 salt: str = "") -> dict:
    raw = f"{claim}\n{note}"
    claim_s, note_s = sanitise(claim, cfg, 600), sanitise(note, cfg)
    h = dedup_hash("finding", reviewer, domain, file, claim_s, salt)  # salt: planted runs stay distinct per run
    return {"schema": SCHEMA_TAG, "kind": "finding", "id": h[:16], "hash": h, "recorded_utc": now_utc(),
            "event_utc": event_utc, "source": source, "reviewer": reviewer, "model": model,
            "severity": normalise_severity(severity, cfg), "domain": sanitise(domain or "general", cfg, 60),
            "file": sanitise(file or "", cfg, 200), "claim": claim_s, "note": note_s,
            "review_verdict": verdict, "injection_flags": injection_flags(raw, cfg), "status": "open"}


def price_for(cfg, model: str | None):
    pr = cfg["prices_usd_per_mtok"]
    if not model:
        return None
    return next((v for k, v in sorted(pr.items(), key=lambda kv: -len(kv[0])) if not k.startswith("_") and model.startswith(k)), None)


def deepseek_offpeak(when_iso: str | None) -> bool:
    if not when_iso:
        return False
    t = _dt.datetime.fromisoformat(when_iso.replace("Z", "+00:00")).astimezone(_dt.timezone.utc)
    return not (t.weekday() < 5 and (1 <= t.hour < 4 or 6 <= t.hour < 10))


def compute_cost(cfg, model, tokens: dict, when_iso=None):
    p = price_for(cfg, model)
    if p is None:
        return None, f"unknown: no price on file for {model}"
    cached, cw = tokens.get("cached") or 0, tokens.get("cache_write") or 0
    miss = max((tokens.get("input") or 0) - cached - cw, 0)
    c = (miss * p["in"] + cached * p["cached"] + cw * p.get("cache_write", p["in"]) + (tokens.get("output") or 0) * p["out"]) / 1e6
    note = "computed from harness/ledger.json prices"
    if "offpeak_factor" in p and deepseek_offpeak(when_iso):
        c *= p["offpeak_factor"]; note += " (off-peak)"
    return round(c, 6), note


def make_cost(cfg, *, reviewer, model, tokens, source, cost_usd=None, cost_basis=None, event_utc=None) -> dict:
    if cost_usd is None:
        cost_usd, cost_basis = compute_cost(cfg, model, tokens, event_utc)
    h = dedup_hash("cost", reviewer, source.get("type"), source.get("ref"), source.get("run_id"), source.get("scope"), model)
    return {"schema": SCHEMA_TAG, "kind": "cost", "id": h[:16], "hash": h, "recorded_utc": now_utc(),
            "event_utc": event_utc, "source": source, "reviewer": reviewer, "model": model,
            "tokens": {k: tokens.get(k) for k in ("input", "cached", "cache_write", "output", "reasoning")},
            "cost_usd": None if cost_usd is None else round(float(cost_usd), 6), "cost_basis": cost_basis or "reported"}


def make_status(finding_id: str, status: str, source: dict, issue_number=None, note: str | None = None) -> dict:
    """Status record. deferred / superseded (v1.2) need a note: the reason or the revisit condition."""
    if status not in STATUSES:
        raise ValueError(f"unknown status {status!r}")
    h = dedup_hash("status", finding_id, status, source.get("ref"))
    rec = {"schema": SCHEMA_TAG_V12 if status in PARKED else SCHEMA_TAG, "kind": "status", "id": h[:16], "hash": h,
           "recorded_utc": now_utc(), "source": source, "finding_id": finding_id, "status": status,
           "issue_number": issue_number}
    if note is not None:
        rec["note"] = note
    elif status in PARKED:
        raise ValueError(f"status {status!r} needs a note (reason / revisit condition)")
    return rec


def make_mirror(finding_id: str, issue_number: int, source: dict) -> dict:
    h = dedup_hash("mirror", finding_id, issue_number)
    return {"schema": SCHEMA_TAG, "kind": "mirror", "id": h[:16], "hash": h, "recorded_utc": now_utc(),
            "source": source, "finding_id": finding_id, "issue_number": int(issue_number)}

# ------------------------------------------------------------------ receipts + review class (v1.1, round 4)
class ReceiptRefused(Exception):
    pass


def make_receipt(evidence: dict, digest: str, attestation: str, ref: str, run_id=None) -> dict:
    h = dedup_hash("receipt", evidence.get("component"), evidence.get("head_sha"), digest)
    return {"schema": SCHEMA_TAG, "kind": "receipt", "id": h[:16], "hash": h, "recorded_utc": now_utc(),
            "event_utc": evidence.get("generated_utc"),
            "source": {"type": "receipt_artifact", "ref": ref, "run_id": str(run_id or evidence.get("run_id")),
                       "head_sha": evidence.get("head_sha"), "scope": evidence.get("job")},
            "reviewer": "Gateway" if evidence.get("component") == "mcp-gateway" else "Cursor",
            "component": evidence.get("component"), "artifact_digest": digest, "attestation": attestation[:300],
            "target_files": list(evidence.get("files") or []), "evidence": evidence, "ok": evidence.get("result") == "pass",
            "summary": f"{evidence.get('component')} at {str(evidence.get('head_sha'))[:12]}: "
                       f"{evidence.get('numeric_checks')} numeric checks pass, run {evidence.get('run_url')}"}


def accept_receipt(evidence_bytes: bytes, ref: str, run_meta: dict | None, verifier=None, env=os.environ) -> dict:
    """Turn an uploaded receipt into a ledger record, or raise ReceiptRefused. CI-only: needs GITHUB_ACTIONS, the
    producing run's metadata (workflow path, head sha, run id from the workflow_run event / API) and a signature
    verifier. There is no local write path: called outside Actions it always refuses."""
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    import receipt as R  # local import: receipt.py imports nothing from here
    if env.get("GITHUB_ACTIONS") != "true" or not run_meta or verifier is None:
        raise ReceiptRefused("receipt ingest runs only inside the ledger workflow (no local/Cursor/reviewer write path)")
    ev = json.loads(evidence_bytes)
    if R.canonical(ev) != evidence_bytes.strip():
        raise ReceiptRefused("evidence.json is not in canonical form (edited after CI wrote it)")
    for k_ev, k_run in (("workflow", "workflow_path"), ("head_sha", "head_sha"), ("run_id", "run_id")):
        if str(ev.get(k_ev)) != str(run_meta.get(k_run)):
            raise ReceiptRefused(f"evidence {k_ev}={ev.get(k_ev)} does not match the producing run ({run_meta.get(k_run)})")
    res = R.verify_receipt(ev, R.digest(evidence_bytes.strip()), attest=verifier)
    if not res["ok"]:
        raise ReceiptRefused("; ".join(res["reasons"]))
    return make_receipt(ev, res["digest"], res["attestation"], ref, run_meta.get("run_id"))


def make_class(finding_id: str, review_class: str, why: str) -> dict:
    h = dedup_hash("class", finding_id, review_class)
    return {"schema": SCHEMA_TAG, "kind": "class", "id": h[:16], "hash": h, "recorded_utc": now_utc(),
            "source": {"type": "backfill", "ref": why}, "finding_id": finding_id, "review_class": review_class}


def review_classes(records: list[dict]) -> dict[str, str]:
    """id -> effective review_class for finding and cost records (record field, else class record, else legacy)."""
    out = {r["id"]: r.get("review_class") or "legacy" for r in records if r["kind"] in ("finding", "cost")}
    explicit = {r["id"] for r in records if r["kind"] in ("finding", "cost") and r.get("review_class")}
    for r in records:
        if r["kind"] == "class" and r["finding_id"] in out and r["finding_id"] not in explicit:
            out[r["finding_id"]] = r["review_class"]
    return out


def legacy_backfill(records: list[dict]) -> list[dict]:
    have = {r["finding_id"] for r in records if r["kind"] == "class"}
    return [make_class(r["id"], "legacy", "pre-receipt-gate backfill (no receipt)") for r in records
            if r["kind"] in ("finding", "cost") and not r.get("review_class") and r["id"] not in have]


def parse_artifact_dir(d: Path, cfg: dict, ref: str, run_id=None, run_meta=None, verifier=None, refused=None) -> list[dict]:
    d = Path(d)
    out = []
    rc = None
    rcf = next(iter(sorted(d.rglob("review_class.json"))), None)
    if rcf is not None:
        try:
            rc = json.loads(rcf.read_text(encoding="utf-8")).get("review_class")
        except (json.JSONDecodeError, AttributeError):
            rc = None
        rc = rc if rc in REVIEW_CLASSES else None
    for f in sorted(d.rglob("evidence.json")):
        try:
            out.append(accept_receipt(f.read_bytes(), ref, run_meta, verifier))
        except (ReceiptRefused, json.JSONDecodeError) as e:
            if refused is not None:
                refused.append(f"{f}: {e}")
    for f in sorted(d.rglob("*.json")):
        try:
            obj = json.loads(f.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, UnicodeDecodeError):
            continue
        if not isinstance(obj, (dict, list)):
            continue
        if f.name == "verdict.json":
            out += parse_verdict_json(obj, cfg, ref, run_id)
        elif f.name == "ping.json":
            out += parse_ping_json(obj, cfg, ref, run_id)
        elif f.name == "gateway_run.json":
            for g in (obj if isinstance(obj, list) else [obj]):
                out += parse_gateway_run(g, cfg, ref, run_id)
        elif f.name == "results.json" and isinstance(obj, (dict, list)) and ("tavily" in f.parent.name.lower() or "tavily" in ref.lower()):
            out += parse_tavily_json(obj, ref, cfg)
    if rc:
        for r in out:
            if r["kind"] in ("finding", "cost"):
                r["review_class"] = rc
    return out


