import ledger_lib

KINDS = ("info_request", "info_answer", "info_invalidate", "cost")

# decisions in there"). Records carrying any of these fields are refused.
DECISION_FIELDS = ("decision", "decisions", "verdict", "verdicts", "score", "scores", "choice", "design_choice",
                   "recommendation", "recommendations", "ruling", "approved", "adopted")
FACT_SOURCES = ("tavily", "claude_code")          # fetched (looked-up) answers; file reads are not promoted
REFERENCE_FILE = "facts.jsonl"
# In-round decisions cache (Claude Code's decision parts, delivered to askers; never in the store or the reference
# folder). Sealed into <round-dir>/archive/ at close (moved, never deleted); no model tool can reach the archive.
DECISIONS_CACHE = "decisions_cache.jsonl"
ARCHIVE_DIR = "archive"
TS_FMT = "%Y-%m-%dT%H:%M:%SZ"


def now_utc() -> str:
    return datetime.now(timezone.utc).strftime(TS_FMT)


def _ts(s: str) -> float:
    return datetime.strptime(s, TS_FMT).replace(tzinfo=timezone.utc).timestamp()


def norm_question(q: str) -> str:
    return re.sub(r"[\s?.!,;:]+$", "", ledger_lib._norm(q))


def epoch_of(paths) -> str:
    h = hashlib.sha256()
    for p in paths:
        p = Path(p)
        h.update(str(p.name).encode() + b"\x1f")
        h.update(p.read_bytes() if p.is_file() else b"<missing>")
        h.update(b"\x1e")
    return h.hexdigest()


def store_key(question: str, scope: str, epoch: str) -> str:
    return ledger_lib.dedup_hash(norm_question(question), scope, epoch)[:16]


def verify_append_only(old_text: str, new_text: str) -> bool:
    return new_text.startswith(old_text)


@contextmanager
def _locked(path: Path):
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "a+") as fh:
        fcntl.flock(fh, fcntl.LOCK_EX)
        try:
            yield fh
        finally:
            fcntl.flock(fh, fcntl.LOCK_UN)


class Store:
    def __init__(self, store_dir):
        self.dir = Path(store_dir)
        self.log = self.dir / "info.jsonl"
        self.index_path = self.dir / "index.json"
        self.inflight = self.dir / "inflight"
        self._lockfile = self.dir / ".store.lock"

    # ---------- append-only log ----------
    def append(self, kind: str, **fields) -> dict:
        if kind not in KINDS:
            raise ValueError(f"unknown record kind {kind!r}")
        bad = [k for k in fields if k.lower() in DECISION_FIELDS]
        if bad:
            raise ValueError(f"store holds fetched answers only; refusing decision-type field(s) {bad}")
        rec = {"kind": kind, "ts": now_utc(), "id": secrets.token_hex(8), **fields}
        line = json.dumps(rec, sort_keys=True) + "\n"
        with _locked(self._lockfile):
            with open(self.log, "a") as fh:
                fh.write(line)
                fh.flush()
                os.fsync(fh.fileno())
            if kind in ("info_answer", "info_invalidate"):
                idx = self._read_index()
                self._apply(idx, rec)
                self._write_index(idx)
        return rec

    def records(self) -> list[dict]:
        if not self.log.is_file():
            return []
        return [json.loads(x) for x in self.log.read_text().splitlines() if x.strip()]

    # ---------- index ----------
    @staticmethod
    def _apply(idx: dict, rec: dict) -> None:
        if rec["kind"] == "info_answer":
            idx[rec["store_key"]] = rec
        elif rec["kind"] == "info_invalidate":
            idx.pop(rec["store_key"], None)

    def _read_index(self) -> dict:
        if not self.index_path.is_file():
            return {}
        try:
            return json.loads(self.index_path.read_text())
        except json.JSONDecodeError:
            return self.rebuild_index(write=False)

    def _write_index(self, idx: dict) -> None:
        tmp = self.index_path.with_suffix(".json.tmp")
        tmp.write_text(json.dumps(idx, sort_keys=True, indent=1))
        os.replace(tmp, self.index_path)

    def rebuild_index(self, write: bool = True) -> dict:
        idx: dict = {}
        for r in self.records():
            if r["kind"] in ("info_answer", "info_invalidate"):
                self._apply(idx, r)
        if write:
            self.dir.mkdir(parents=True, exist_ok=True)
            self._write_index(idx)
        return idx

    # ---------- parked results ----------
    def lookup(self, key: str, max_age_s) -> dict | None:
        """Latest valid parked answer for key. max_age_s=False means answers never expire."""
        rec = self._read_index().get(key)
        if rec is None:
            return None
        if max_age_s is not False and (time.time() - _ts(rec["ts"])) > float(max_age_s):
            return None
        return rec

    def park(self, key: str, **fields) -> dict:
        return self.append("info_answer", store_key=key, **fields)

    def invalidate(self, key: str, reason: str) -> dict:
        return self.append("info_invalidate", store_key=key, reason=reason)

    # ---------- spend ----------
    def spent(self) -> dict:
        """usd = everything (round total: model replies + fetches); fetch_usd = info_fetch records only
        (fetch_budget_usd); reply_usd = model_reply records (round_budget.py)."""
        usd, credits, fetch, reply = 0.0, 0, 0.0, 0.0
        for r in self.records():
            if r["kind"] == "cost":
                c = float(r.get("cost_usd") or 0)
                usd += c
                credits += int(r.get("credits") or 0)
                if r.get("source_type") == "model_reply":
                    reply += c
                else:
                    fetch += c
        return {"usd": usd, "credits": credits, "fetch_usd": fetch, "reply_usd": reply}

    # ---------- waiters queue ----------
    def _lock_path(self, key: str) -> Path:
        return self.inflight / f"{key}.lock"

    def acquire(self, key: str, owner: str, lease_s) -> bool:
        """True if this caller now owns the fetch for key. Takes over a marker whose lease has expired."""
        self.inflight.mkdir(parents=True, exist_ok=True)
        p = self._lock_path(key)
        body = json.dumps({"owner": owner, "pid": os.getpid(), "started_utc": now_utc(),
                           "lease_until": time.time() + float(lease_s)})
        for _ in range(2):
            try:
                fd = os.open(p, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            except FileExistsError:
                try:
                    held = json.loads(p.read_text() or "{}")
                except (OSError, json.JSONDecodeError):
                    held = {}
                if held and time.time() <= float(held.get("lease_until", 0)):
                    return False
                stale = p.with_name(f"{p.name}.expired-{secrets.token_hex(4)}")
                try:
                    os.replace(p, stale)       # move the expired marker aside; only one taker wins the O_EXCL
                    self.append("info_request", store_key=key, event="lease_takeover", by=owner,
                                previous=held)
                except FileNotFoundError:
                    pass
                continue
            with os.fdopen(fd, "w") as fh:
                fh.write(body)
            return True
        return False

    def release(self, key: str) -> None:
        try:
            self._lock_path(key).unlink()
        except FileNotFoundError:
            pass

    def in_flight(self, key: str) -> bool:
        return self._lock_path(key).exists()

    def wait_for(self, key: str, timeout_s, poll_s, max_age_s):
        """Wait for another process's fetch. Returns ("answer", rec) | ("released", None) | ("timeout", None)."""
        t_end = time.monotonic() + float(timeout_s)
        while True:
            rec = self.lookup(key, max_age_s)
            if rec is not None:
                return "answer", rec
            if not self.in_flight(key):
                rec = self.lookup(key, max_age_s)
                return ("answer", rec) if rec else ("released", None)
            if time.monotonic() >= t_end:
                return "timeout", None
            time.sleep(float(poll_s))


# ---------- promotion: round store -> Claude Code reference folder (fetched facts only) ----------
def is_fetched_fact(rec: dict) -> tuple[bool, str]:
    """(ok, why). Only an answered info_answer fetched by Tavily or Claude Code, with sources, is a fact."""
    if rec.get("kind") != "info_answer":
        return False, f"kind {rec.get('kind')!r} is not info_answer"
    bad = [k for k in rec if str(k).lower() in DECISION_FIELDS]
    if bad:
        return False, f"decision-type field(s) {bad}"
    if rec.get("status") != "answered":
        return False, f"status {rec.get('status')!r} is not answered"
    if rec.get("answered_by") not in FACT_SOURCES:
        return False, f"answered_by {rec.get('answered_by')!r} is not a fetch"
    if not rec.get("cites"):
        return False, "no sources"
    if rec.get("used_reference"):
        return False, "drawn from the reference folder already"
    return True, ""


def promote_facts(store_dir, reference_dir, records=None) -> dict:
    """Append fetched-fact records from a round store to <reference_dir>/facts.jsonl (append-only, dedup by id).

    st = Store(store_dir)
    recs = st.records() if records is None else records
    ref = Path(reference_dir)
    ref.mkdir(parents=True, exist_ok=True)
    out = ref / REFERENCE_FILE
    have = set()
    if out.is_file():
        have = {json.loads(x).get("id") for x in out.read_text().splitlines() if x.strip()}
    copied, refused = [], []
    keep = ("id", "ts", "store_key", "question", "scope", "answer", "cites", "answered_by", "run_id")
    with _locked(ref / ".facts.lock"):
        with open(out, "a") as fh:
            for r in recs:
                ok, why = is_fetched_fact(r)
                if not ok:
                    refused.append({"id": r.get("id"), "kind": r.get("kind"), "why": why})
                    continue
                if r.get("id") in have:
                    continue
                fh.write(json.dumps({k: r.get(k) for k in keep}, sort_keys=True) + "\n")
                have.add(r.get("id"))
                copied.append(r.get("id"))
    return {"copied": copied, "refused": refused}


# ---------- decisions cache: seal at close ----------
def sealed_path(round_dir, run_id: str) -> Path:
    if not run_id or not re.fullmatch(r"[A-Za-z0-9_.-]+", str(run_id)):
        raise ValueError(f"bad run_id for sealing: {run_id!r}")
    return Path(round_dir) / ARCHIVE_DIR / f"decisions_cache_sealed_{run_id}.jsonl"


def seal_decisions_cache(round_dir, run_id: str) -> Path | None:
    """MOVE <round-dir>/decisions_cache.jsonl to archive/decisions_cache_sealed_<run_id>.jsonl (read-only).
    Nothing is deleted. Refuses (FileExistsError) to overwrite an existing sealed file. No cache -> None."""
    src = Path(round_dir) / DECISIONS_CACHE
    dst = sealed_path(round_dir, run_id)
    if not src.exists():
        return None
    if dst.exists():
        raise FileExistsError(f"{dst} already exists; refusing to overwrite a sealed decisions cache")
    dst.parent.mkdir(parents=True, exist_ok=True)
    with _locked(Path(round_dir) / ".decisions.lock"):
        if dst.exists():
            raise FileExistsError(f"{dst} already exists; refusing to overwrite a sealed decisions cache")
        os.rename(src, dst)
    os.chmod(dst, 0o444)
    return dst

